// Build-time map generator.
// Input : data-src/ne50.json (Natural Earth 50m admin-0), data-src/places10.json (NE 10m populated places)
// Output: public/data/world.topo.json  (province geometries as TopoJSON)
//         public/data/provinces.json   (province + country metadata, adjacency)
// Provinces are generated by seeding real cities inside each country and clipping the
// Voronoi diagram of those seeds to the country shape, so every province is named after a real city.
import fs from 'node:fs';
import { Delaunay } from 'd3-delaunay';
import polygonClipping from 'polygon-clipping';
import { geoArea, geoContains, geoCentroid, geoBounds } from 'd3-geo';
import { topology } from 'topojson-server';
import { presimplify, simplify, quantile } from 'topojson-simplify';

const R = 6371;
const ne = JSON.parse(fs.readFileSync('data-src/ne50.json', 'utf8'));
const places = JSON.parse(fs.readFileSync('data-src/places10.json', 'utf8'));

// Dependencies / disputed areas -> controlling sovereign tag used by the game.
const SOV_FIX = {
  US1: 'USA', GB1: 'GBR', NZ1: 'NZL', FR1: 'FRA', DN1: 'DNK', AU1: 'AUS', KA1: 'KAZ',
  IS1: 'ISR', CU1: 'CUB', CH1: 'CHN', FI1: 'FIN', NL1: 'NLD',
};
const ADM_FIX = { PSX: 'PSE', SAH: 'MAR', SOL: 'SOM', CYN: 'CYP', KAS: 'IND' };

function ownerOf(p) {
  if (ADM_FIX[p.ADM0_A3]) return ADM_FIX[p.ADM0_A3];
  if (SOV_FIX[p.SOV_A3]) return SOV_FIX[p.SOV_A3];
  if (p.TYPE === 'Sovereign country' || p.TYPE === 'Country' || p.TYPE === 'Disputed') return p.ADM0_A3;
  return p.SOV_A3;
}

// ---- group features per owner ----
const countries = new Map(); // tag -> {tag, name, pop, gdp, polys: [[ring...]...]}
for (const f of ne.features) {
  const p = f.properties;
  if (p.ADM0_A3 === 'ATA') continue;
  const tag = ownerOf(p);
  if (!countries.has(tag)) countries.set(tag, { tag, name: null, nameEn: null, pop: 0, gdp: 0, polys: [] });
  const c = countries.get(tag);
  if (p.ADM0_A3 === tag || (!c.name && tag === p.ADM0_A3)) {
    c.name = p.NAME_KO || p.NAME;
    c.nameEn = p.NAME;
  }
  c.pop += p.POP_EST || 0;
  c.gdp += p.GDP_MD || 0;
  const g = f.geometry;
  const polys = g.type === 'Polygon' ? [g.coordinates] : g.coordinates;
  for (const poly of polys) c.polys.push(poly);
}
for (const c of countries.values()) {
  if (!c.name) {
    const f = ne.features.find((x) => ownerOf(x.properties) === c.tag);
    c.name = f.properties.NAME_KO || f.properties.NAME;
    c.nameEn = f.properties.NAME;
  }
}

// ---- antimeridian handling: choose a longitude shift that minimises span ----
function lonShift(polys) {
  let min = 999, max = -999;
  for (const poly of polys) for (const [x] of poly[0]) { min = Math.min(min, x); max = Math.max(max, x); }
  if (max - min < 270) return 0;
  // try shifting negatives east, or positives west
  const spans = [0, 360, -360].map((s) => {
    let a = 999, b = -999;
    for (const poly of polys) for (const [x] of poly[0]) {
      const v = s === 360 && x < 0 ? x + 360 : s === -360 && x > 0 ? x - 360 : x;
      a = Math.min(a, v); b = Math.max(b, v);
    }
    return { s, span: b - a };
  });
  spans.sort((a, b) => a.span - b.span);
  return spans[0].s;
}
const applyShift = (x, s) => (s === 360 && x < 0 ? x + 360 : s === -360 && x > 0 ? x - 360 : x);

// ---- cities per country ----
const citiesByTag = new Map();
for (const f of places.features) {
  const p = f.properties;
  const tag = ADM_FIX[p.ADM0_A3] ?? (countries.has(p.ADM0_A3) ? p.ADM0_A3 : SOV_FIX[p.SOV_A3] ?? p.SOV_A3);
  if (!countries.has(tag)) continue;
  if (!citiesByTag.has(tag)) citiesByTag.set(tag, []);
  citiesByTag.get(tag).push({
    name: p.NAME_KO || p.NAME,
    lon: p.LONGITUDE, lat: p.LATITUDE,
    pop: p.POP_MAX || 0,
    capital: p.ADM0CAP === 1 && (p.ADM0_A3 === tag),
  });
}

function km(a, b) {
  const toR = Math.PI / 180;
  const dLat = (b.lat - a.lat) * toR, dLon = (b.lon - a.lon) * toR;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toR) * Math.cos(b.lat * toR) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

const DIRS = ['북부', '북동부', '동부', '남동부', '남부', '남서부', '서부', '북서부'];
function dirName(from, to) {
  const ang = Math.atan2(to.lat - from.lat, (to.lon - from.lon) * Math.cos(from.lat * Math.PI / 180));
  // 0 = east; convert to compass index where 0 = north
  let deg = 90 - (ang * 180) / Math.PI;
  deg = ((deg % 360) + 360) % 360;
  return DIRS[Math.round(deg / 45) % 8];
}

// deterministic RNG
let seed = 1234567;
const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0) / 4294967296);

const provinces = [];
const geometries = [];

for (const c of countries.values()) {
  const s = lonShift(c.polys);
  const polys = c.polys.map((poly) => poly.map((ring) => ring.map(([x, y]) => [applyShift(x, s), y])));
  const feature = { type: 'Feature', geometry: { type: 'MultiPolygon', coordinates: polys }, properties: {} };
  const areaKm = geoArea(feature) * R * R;
  c.area = areaKm;
  // denser provinces where people live (Korea, Japan, Europe), sparse in Siberia / Sahara
  const density = c.pop / Math.max(1, areaKm);
  const densF = Math.min(3, Math.max(1, Math.sqrt(density / 50)));
  let target = Math.max(1, Math.round((Math.pow(areaKm / 1000, 0.6) / 2) * densF));
  target = Math.min(target, 220);
  const spacing = Math.sqrt(areaKm / target) * 0.7;

  // planar bbox in shifted lon
  let minX = 999, minY = 999, maxX = -999, maxY = -999;
  for (const poly of polys) for (const [x, y] of poly[0]) {
    minX = Math.min(minX, x); maxX = Math.max(maxX, x); minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }
  const lat0 = (minY + maxY) / 2;
  const kx = Math.cos((lat0 * Math.PI) / 180);

  const inside = (lon, lat) => geoContains(feature, [lon, lat]);

  // seeds from cities, biggest first
  const cities = (citiesByTag.get(c.tag) ?? [])
    .map((ct) => ({ ...ct, lon: applyShift(ct.lon, s) }))
    .sort((a, b) => (b.capital - a.capital) || b.pop - a.pop);
  const seeds = [];
  for (const ct of cities) {
    if (seeds.length >= target) break;
    // coastal cities may sit just outside the simplified coastline; keep them (cell gets clipped to land)
    if (seeds.some((sd) => km(sd, ct) < spacing * (ct.capital ? 0.3 : 1))) continue;
    seeds.push({ ...ct, filler: false });
  }
  // filler seeds on a jittered grid for empty areas
  if (seeds.length < target || seeds.length === 0) {
    const stepDeg = spacing / 111;
    for (let y = minY + stepDeg / 2; y < maxY; y += stepDeg) {
      const kxy = Math.max(0.15, Math.cos((y * Math.PI) / 180));
      for (let x = minX + stepDeg / kxy / 2; x < maxX; x += stepDeg / kxy) {
        const p = { lon: x + (rnd() - 0.5) * stepDeg * 0.5 / kxy, lat: y + (rnd() - 0.5) * stepDeg * 0.5 };
        if (!inside(p.lon, p.lat)) continue;
        if (seeds.some((sd) => km(sd, p) < spacing * 0.9)) continue;
        seeds.push({ ...p, name: null, pop: 0, capital: false, filler: true });
      }
    }
  }
  if (seeds.length === 0) {
    // tiny islands: use centroid of the largest polygon
    const big = polys.slice().sort((a, b) => b[0].length - a[0].length)[0];
    const ctd = geoCentroid({ type: 'Polygon', coordinates: big });
    seeds.push({ lon: ctd[0], lat: ctd[1], name: null, pop: 0, capital: false, filler: true });
  }
  // name fillers after nearest real city (+ direction) or the country
  const named = seeds.filter((sd) => !sd.filler);
  let fillerNo = 0;
  for (const sd of seeds) {
    if (!sd.filler) continue;
    fillerNo++;
    if (named.length) {
      let best = named[0], bd = Infinity;
      for (const n of named) { const d = km(n, sd); if (d < bd) { bd = d; best = n; } }
      sd.name = `${best.name} ${dirName(best, sd)}`;
    } else {
      sd.name = seeds.length > 1 ? `${c.name} ${fillerNo}` : c.name;
    }
  }
  // de-duplicate names
  const seen = new Map();
  for (const sd of seeds) {
    const n = seen.get(sd.name) ?? 0;
    seen.set(sd.name, n + 1);
    if (n > 0) sd.name = `${sd.name} ${n + 1}`;
  }
  if (!seeds.some((sd) => sd.capital)) {
    const big = seeds.slice().sort((a, b) => b.pop - a.pop)[0];
    big.capital = true;
  }

  // Voronoi in locally scaled planar coords
  const pad = 2;
  const pts = seeds.map((sd) => [sd.lon * kx, sd.lat]);
  const cellsPolys = [];
  if (seeds.length === 1) {
    cellsPolys.push(polys);
  } else {
    const del = Delaunay.from(pts);
    const vor = del.voronoi([(minX - pad) * kx, minY - pad, (maxX + pad) * kx, maxY + pad]);
    for (let i = 0; i < seeds.length; i++) {
      const cell = vor.cellPolygon(i);
      if (!cell) { cellsPolys.push([]); continue; }
      const ring = cell.map(([x, y]) => [x / kx, y]);
      let clipped;
      try {
        clipped = [];
        for (const poly of polys) {
          const part = polygonClipping.intersection([ring], poly);
          for (const pp of part) clipped.push(pp);
        }
      } catch (e) {
        clipped = [];
      }
      cellsPolys.push(clipped);
    }
  }

  seeds.forEach((sd, i) => {
    const mp = cellsPolys[i];
    if (!mp || mp.length === 0) return;
    // polygon-clipping returns CCW exteriors; d3-geo wants CW exteriors on the sphere.
    const fixed = mp.map((poly) => poly.map((ring) => ring.slice().reverse()));
    const geom = { type: 'MultiPolygon', coordinates: fixed };
    let a = geoArea(geom);
    if (a > 2 * Math.PI) {
      // wrong winding -> flip back
      geom.coordinates = mp;
      a = geoArea(geom);
    }
    const area = a * R * R;
    if (area < 1) return;
    const id = provinces.length;
    const cen = geoCentroid(geom);
    provinces.push({
      id,
      owner: c.tag,
      name: sd.name,
      cityPop: sd.pop,
      capital: !!sd.capital,
      area: Math.round(area),
      lon: +(+sd.lon > 180 ? sd.lon - 360 : sd.lon < -180 ? sd.lon + 360 : sd.lon).toFixed(3),
      lat: +sd.lat.toFixed(3),
      cx: +cen[0].toFixed(3),
      cy: +cen[1].toFixed(3),
    });
    geometries.push({ type: 'Feature', id, properties: { id }, geometry: geom });
  });
}

// make sure every country kept a capital
const byOwner = new Map();
for (const p of provinces) { if (!byOwner.has(p.owner)) byOwner.set(p.owner, []); byOwner.get(p.owner).push(p); }
for (const [, list] of byOwner) {
  if (!list.some((p) => p.capital)) list.slice().sort((a, b) => b.cityPop - a.cityPop || b.area - a.area)[0].capital = true;
}

// ---- adjacency via shared (rounded) vertices ----
const vkey = (x, y) => `${Math.round(((x % 360) + 540) % 360 * 1e3)},${Math.round(y * 1e3)}`;
const vmap = new Map();
geometries.forEach((g) => {
  const set = new Set();
  for (const poly of g.geometry.coordinates) for (const ring of poly) for (const [x, y] of ring) set.add(vkey(x, y));
  for (const k of set) {
    if (!vmap.has(k)) vmap.set(k, []);
    vmap.get(k).push(g.id);
  }
});
const adj = provinces.map(() => new Map());
const lonely = provinces.map(() => 0);
for (const ids of vmap.values()) {
  if (ids.length < 2) { lonely[ids[0]]++; continue; }
  for (const a of ids) for (const b of ids) if (a !== b) adj[a].set(b, (adj[a].get(b) ?? 0) + 1);
}
provinces.forEach((p) => {
  p.adj = [...adj[p.id].entries()].filter(([, n]) => n >= 2).map(([b]) => b).sort((a, b) => a - b);
  p.coastal = lonely[p.id] >= 4 || p.adj.length === 0;
});

// ---- topology ----
const fc = { type: 'FeatureCollection', features: geometries };
let topo = topology({ provinces: fc }, 1e5);
topo = presimplify(topo);
topo = simplify(topo, quantile(topo, 0.35));

fs.mkdirSync('public/data', { recursive: true });
fs.writeFileSync('public/data/world.topo.json', JSON.stringify(topo));
const countryMeta = [...countries.values()]
  .filter((c) => byOwner.has(c.tag))
  .map((c) => ({ tag: c.tag, name: c.name, nameEn: c.nameEn, pop: c.pop, gdpMd: c.gdp, area: Math.round(c.area) }));
fs.writeFileSync('public/data/provinces.json', JSON.stringify({ countries: countryMeta, provinces }));

const kor = provinces.filter((p) => p.owner === 'KOR');
console.log('countries', countryMeta.length, 'provinces', provinces.length);
console.log('KOR', kor.map((p) => `${p.name}${p.capital ? '*' : ''}[${p.adj.length}]`).join(', '));
console.log('RUS', provinces.filter((p) => p.owner === 'RUS').length, 'USA', provinces.filter((p) => p.owner === 'USA').length);
console.log('coastal', provinces.filter((p) => p.coastal).length, 'KOR coastal', kor.filter((p) => p.coastal).map((p) => p.name).join(','));
console.log('isolated', provinces.filter((p) => p.adj.length === 0).length);
console.log('topo bytes', JSON.stringify(topo).length, 'meta bytes', JSON.stringify(provinces).length);
